function runSpringCamp(){if(universe.phase!=='complete'){setStatus('Finish the season before spring development.');return}let ds=ensureDevelopmentState();if(ds.springRun){setStatus('Spring development has already been completed.');return}let u=selected(),report=[];for(const t of universe.teams){for(const p of t.roster){p.lastDevelopmentDelta=0;let d=applyDevelopmentPhase(p,t,'spring');if(t===u)report.push({id:p.id,name:p.name,pos:p.pos,delta:d,physical:p.lastPhysicalChange})}if(t!==u&&Math.random()<.35)t.trainingFocus=pick(Object.keys(TEAM_TRAINING));autoRoleDepth(t,false)}ds.springRun=true;ds.springReport=report.sort((a,b)=>b.delta-a.delta);ds.battles=buildCampBattles(u,'spring');setStatus('Spring development complete. Staff evaluations have tightened.');render()}
