function findUserGame(){if(universe.phase!=='regular'||universe.week>=12)return null;const n=$('#userTeam').value;return universe.schedule[universe.week].find(g=>!g.played&&(g.home===n||g.away===n))||null}

function userWeekResult(u){let w=universe.week;if(w<=0)return null;let g=u.schedule.find(g=>g.week===w&&g.played);if(!g)return null;let userHome=g.home===u.name,userPts=userHome?g.score?.[1]:g.score?.[0],oppPts=userHome?g.score?.[0]:g.score?.[1],opp=userHome?g.away:g.home;return {win:g.winner===u.name,opp,userPts,oppPts,loc:userHome?'vs':'@'}}
function buildPreseasonHub(){universe.weeklyHub=[{type:'action',kicker:'ROSTER',main:'Set your role depth chart',sub:'X/Z/slot, nickel, rush edge and special teams are live.'},{type:'action',kicker:'RECRUITING',main:'Build an initial recruiting board',sub:'Auto-target 20 or manually chase players who fit the roster.'},{type:'action',kicker:'REDSHIRTS',main:'Review freshman redshirts',sub:'Protected players can appear in no more than four games.'}]}
function buildWeeklyHub(beforeRank=selected()?.rank||null){const u=selected(),items=[],res=userWeekResult(u);if(res)items.push({type:res.win?'good-news':'bad-news',kicker:'FINAL',main:`${res.win?'Win':'Loss'} ${res.userPts}–${res.oppPts} ${res.loc} ${res.opp}`,sub:`${u.w}-${u.l} overall · ${u.cw}-${u.cl} conference`});if(beforeRank&&u.rank!==beforeRank)items.push({type:u.rank<beforeRank?'good-news':'alert',kicker:'RANKINGS',main:`${u.rank<beforeRank?'Up':'Down'} to #${u.rank}`,sub:`Previous ranking: #${beforeRank}`});let inj=u.roster.filter(p=>(p.injuryHistory||[]).some(x=>x.year===universe.year&&x.week===universe.week)).slice(0,2);for(const p of inj)items.push({type:'bad-news',kicker:'MEDICAL',main:`${p.name}: ${p.injury}`,sub:`Expected absence: ${p.injuryWeeks} week${p.injuryWeeks===1?'':'s'}`});let commits=universe.recruits.filter(r=>r.committed===u.name&&r.commitWeek===universe.week).slice(0,3);for(const r of commits)items.push({type:'good-news',kicker:'COMMITMENT',main:`${'★'.repeat(r.stars)} ${r.pos} ${r.name}`,sub:`#${r.nationalRank} nationally · ${r.homeCity}, ${r.homeState}`});let next=findUserGame();if(next){let opp=T(next.home===u.name?next.away:next.home);items.push({type:'action',kicker:'NEXT UP',main:`Week ${universe.week+1}: ${next.home===u.name?'vs':'@'} ${opp.name}`,sub:`${opp.w}-${opp.l} · #${opp.rank<=25?opp.rank:'—'} · ${opp.offScheme}`})}let risk=u.roster.map(p=>({p,r:transferRisk(p)})).sort((a,b)=>b.r-a.r)[0];if(risk?.r>=42)items.push({type:'alert',kicker:'LOCKER ROOM',main:`${risk.p.name} transfer risk: ${Math.round(risk.r)}`,sub:`${risk.p.role} · morale ${risk.p.morale}`});let hot=universe.recruits.filter(r=>r.targeted&&!r.committed).sort((a,b)=>b.interest-a.interest)[0];if(hot)items.push({type:'action',kicker:'TOP TARGET',main:`${hot.name} · ${hot.interest}%`,sub:`#${hot.nationalRank} ${hot.pos} · ${hot.trend>0?'↑ '+hot.trend:hot.trend<0?'↓ '+Math.abs(hot.trend):'steady'}`});universe.weeklyHub=items.slice(0,9)}

function simulateUserDetailed(){const g=findUserGame();if(!g)return;recoverWeek();const r=detailedGame(T(g.home),T(g.away),false,g.conf);g.played=true;g.score=[r.ap,r.hp];g.winner=r.winner;g.detailed=true;universe.lastDetailedGame=r;universe.latest=[r];ranked();render()}
function simWeek(){if(universe.phase!=='regular'||universe.week>=12)return;recoverWeek();const u=selected(),beforeRank=u.rank;let results=[];for(const g of universe.schedule[universe.week]){if(g.played)continue;let r=gameSim(T(g.home),T(g.away),false,g.conf);g.played=true;g.score=[r.ap,r.hp];g.winner=r.winner;results.push(r)}universe.week++;if(results.length)universe.latest=results;ranked();advanceRecruiting();buildWeeklyHub(beforeRank);if(universe.week===12)universe.phase='confReady';render()}
function simSeason(){while(universe.phase==='regular')simWeek();render()}
function confStand(c){return universe.teams.filter(t=>t.conference===c).map(t=>({t,s:rankingScore(t)})).sort((a,b)=>b.t.cw-a.t.cw||b.t.w-a.t.w||b.s-a.s).map(x=>x.t)}
